@push('styles')<style>.hero{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:18px}.eyebrow{font-size:9px;letter-spacing:.16em;color:#54cde8}.hero h1{margin:6px 0;font-size:clamp(26px,4vw,40px)}.hero p{color:#7898a5;font-size:11px;line-height:1.7;max-width:720px}.back{display:inline-flex;align-items:center;gap:7px;padding:10px 13px;border:1px solid var(--line);border-radius:11px;color:#9db9c2;text-decoration:none;font-size:10px}.card{max-width:1100px;padding:20px;border:1px solid var(--line);border-radius:18px;background:rgba(255,255,255,.02)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.full{grid-column:1/-1}label{display:block;color:#89a7b2;font-size:10px;margin-bottom:7px}input,select,textarea{width:100%;box-sizing:border-box;border:1px solid var(--line);border-radius:10px;background:#061923;color:#e4f3f7;padding:11px;font:inherit;font-size:11px;outline:none}textarea{resize:vertical;line-height:1.6}.slug-box{padding:11px;border:1px solid var(--line);border-radius:10px;background:#061923;color:#6f909d;font-size:10px;overflow:hidden;text-overflow:ellipsis}.cover-upload,.media-box{padding:16px;border:1px solid rgba(67,209,240,.18);border-radius:15px;background:linear-gradient(135deg,rgba(67,209,240,.07),rgba(255,255,255,.02))}.cover-upload{display:grid;grid-template-columns:180px 1fr;gap:18px;align-items:center}.cover-preview{height:130px;border:1px dashed var(--line);border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;color:#688894;font-size:9px;overflow:hidden}.cover-preview img{width:100%;height:100%;object-fit:cover}.cover-preview i{font-size:30px}.cover-upload p,.media-box p{color:#7696a1;font-size:9px;line-height:1.6}.upload-btn{border:1px solid rgba(82,216,240,.3);border-radius:10px;background:rgba(55,197,230,.12);color:#dffaff;padding:11px 13px;cursor:pointer;font-size:10px;font-weight:700}.media-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:15px}.media-item{border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#061923}.media-thumb{height:145px}.media-thumb img,.media-thumb video{width:100%;height:100%;object-fit:cover;display:block}.media-name{padding:8px;font-size:8px;color:#89a7b2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.media-item button{margin:0 8px 9px;border:1px solid rgba(255,100,100,.2);background:rgba(255,80,80,.06);color:#f0a0a0;border-radius:7px;padding:6px 8px;font-size:8px}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.save{border:0;border-radius:11px;padding:12px 16px;background:#29aaca;color:#fff;font-weight:700}.errors{padding:11px;border-radius:10px;margin-bottom:14px;background:rgba(210,65,65,.12);color:#ffb0b0}@media(max-width:700px){.hero{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}.full{grid-column:auto}.cover-upload{grid-template-columns:1fr}.media-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.media-thumb{height:125px}.actions>*{flex:1;text-align:center}}</style>@endpush
